/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TranslocoService } from '@jsverse/transloco';
import { of } from 'rxjs';
import { DocumentService, TemplateNotFoundError } from './document.service';

describe('DocumentService', () => {
  let http: HttpTestingController;
  let service: DocumentService;

  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        {
          provide: TranslocoService,
          useValue: { getActiveLang: () => 'es-ES', translate: (key: string) => key },
        },
      ],
    });
    http = TestBed.inject(HttpTestingController);
    service = TestBed.inject(DocumentService);
  });

  afterEach(() => http.verify());

  const url = (path: string) => (request: { url: string }) => request.url.split('?')[0] === path;

  it('looks for the template from the most specific language to the general one', () => {
    let text: string | undefined;
    service.template('organization/client/report').subscribe((value) => (text = value));
    http.expectOne(url('templates/organization/client/report.es-ES.md')).flush('', { status: 404, statusText: 'NF' });
    http.expectOne(url('templates/organization/client/report.es.md')).flush('', { status: 404, statusText: 'NF' });
    http.expectOne(url('templates/organization/client/report.md')).flush('# General');
    expect(text).toBe('# General');
  });

  it('fails with TemplateNotFoundError when there is none', () => {
    let error: unknown;
    service.template('x').subscribe({ error: (e) => (error = e) });
    ['x.es-ES.md', 'x.es.md', 'x.md'].forEach((file) =>
      http.expectOne(url('templates/' + file)).flush('', { status: 404, statusText: 'NF' }),
    );
    expect(error instanceof TemplateNotFoundError).toBeTrue();
  });

  it('fills the template with the data of the definition', async () => {
    const markdown = new Promise<string>((resolve) =>
      service
        .markdown(
          { template: 'r', data: (item: any) => of({ name: item.name }), fileName: () => 'r' },
          { name: 'ACME' },
        )
        .subscribe(resolve),
    );
    http.expectOne(url('templates/r.es-ES.md')).flush('# {{name}}');
    expect(await markdown).toBe('# ACME');
  });

  it('previews the markdown as html', async () => {
    expect(await service.html('# Hola')).toContain('<h1>Hola</h1>');
  });
});
